window.LSC_DATA={"timelines":{"ep1":{"id":"ep1","title":"Why does ice cream melt?","titleEnd":2.8,"duration":132.758,"lines":{"hello":{"start":3.05,"end":8.566,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.634},{"text":"I'm Curie!","start":5.086,"end":5.757},{"text":"Welcome... to the Little Scientists Club!","start":6.237,"end":8.516}]},"q":{"start":9.366,"end":12.429,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.366,"end":10.358},{"text":"Why does ice cream melt?","start":10.93,"end":12.379}]},"look":{"start":13.529,"end":21.643,"hold":0.4,"chunks":[{"text":"Look!","start":13.529,"end":13.921},{"text":"Here is a lovely ice cream cone.","start":14.385,"end":16.377},{"text":"Ooh... it is cold...","start":16.814,"end":18.906},{"text":"and hard.","start":19.462,"end":20.441},{"text":"Burr!","start":20.902,"end":21.593}]},"sunny":{"start":22.543,"end":28.278,"hold":1.4,"chunks":[{"text":"Now... the sun is shining!","start":22.543,"end":24.164},{"text":"It is warm.","start":24.667,"end":26.022},{"text":"Watch... what happens.","start":26.446,"end":28.228}]},"drip":{"start":30.178,"end":35.722,"hold":0.6,"chunks":[{"text":"Drip...","start":30.178,"end":30.57},{"text":"drip...","start":30.777,"end":31.305},{"text":"drip!","start":31.541,"end":31.866},{"text":"The ice cream is turning into liquid.","start":32.073,"end":34.233},{"text":"It is melting!","start":34.688,"end":35.672}]},"why":{"start":36.822,"end":41.984,"hold":0.8,"chunks":[{"text":"Why?","start":36.822,"end":37.414},{"text":"Let's look closer.","start":38.061,"end":39.316},{"text":"Much... much closer.","start":39.722,"end":41.934}]},"bits":{"start":43.284,"end":47.548,"hold":0.4,"chunks":[{"text":"Ice cream is made of tiny, tiny bits...","start":43.284,"end":45.676},{"text":"far too small to see.","start":46.206,"end":47.498}]},"cold":{"start":48.448,"end":57.515,"hold":0.6,"chunks":[{"text":"When ice cream is cold, the tiny bits hold on to each other... tightly.","start":48.448,"end":52.886},{"text":"So the ice cream stays hard.","start":53.337,"end":54.729},{"text":"We call that...","start":55.188,"end":55.991},{"text":"a solid.","start":56.614,"end":57.465}]},"warm":{"start":58.615,"end":66.566,"hold":0.4,"chunks":[{"text":"When something warm touches the ice cream...","start":58.615,"end":61.235},{"text":"like the sun, or your warm hand...","start":61.759,"end":64.226},{"text":"it gives the tiny bits heat.","start":64.806,"end":66.516}]},"wiggle":{"start":67.466,"end":74.486,"hold":0.6,"chunks":[{"text":"Heat makes the tiny bits wiggle, and jiggle!","start":67.466,"end":70.244},{"text":"They wiggle so much...","start":70.729,"end":72.17},{"text":"that they let go of each other.","start":72.695,"end":74.436}]},"flow":{"start":75.586,"end":82.741,"hold":0.8,"chunks":[{"text":"Now they can slide, and flow.","start":75.586,"end":77.757},{"text":"The ice cream becomes runny, like a liquid.","start":78.15,"end":81.02},{"text":"That... is melting!","start":81.399,"end":82.691}]},"sayit":{"start":84.041,"end":93.656,"hold":1.4,"chunks":[{"text":"So, heat makes solid ice cream melt into a liquid.","start":84.041,"end":87.536},{"text":"Say it with me...","start":87.927,"end":88.991},{"text":"Heat makes it melt!","start":89.599,"end":90.533},{"text":"Heat... makes it... melt!","start":91.871,"end":93.606}]},"freeze":{"start":95.556,"end":106.138,"hold":0.8,"chunks":[{"text":"And guess what?","start":95.556,"end":96.612},{"text":"If we put the melted ice cream back in the freezer...","start":97.246,"end":99.537},{"text":"the cold makes the tiny bits hold hands again, and it turns hard.","start":100.087,"end":104.62},{"text":"It freezes!","start":105.11,"end":106.088}]},"try1":{"start":107.438,"end":111.201,"hold":0.3,"chunks":[{"text":"Let's try it at home!","start":107.438,"end":108.507},{"text":"Ask a grown-up for two ice cubes.","start":108.969,"end":111.151}]},"try2":{"start":112.001,"end":119.249,"hold":1.6,"chunks":[{"text":"Put one in the sunshine...","start":112.001,"end":113.334},{"text":"and one in the shade.","start":113.955,"end":115.103},{"text":"Which one melts first?","start":115.534,"end":117.061},{"text":"Watch... and see!","start":117.607,"end":119.199}]},"bye":{"start":121.349,"end":129.358,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":121.349,"end":122.974},{"text":"Remember... heat makes things melt.","start":123.408,"end":125.2},{"text":"See you next time, at the Little Scientists Club!","start":125.622,"end":128.214},{"text":"Bye-bye!","start":128.678,"end":129.308}]}},"voice":"chirp:achernar"},"ep2":{"id":"ep2","title":"Why does a ball always come down?","titleEnd":2.8,"duration":124.43,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":13.374,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Why does a ball always come down?","start":11.359,"end":13.324}]},"throw":{"start":14.474,"end":21.498,"hold":0.8,"chunks":[{"text":"Curie throws the ball,","start":14.474,"end":15.85},{"text":"up...","start":16.012,"end":16.63},{"text":"up...","start":16.859,"end":17.478},{"text":"up!","start":17.689,"end":18.23},{"text":"And look.","start":18.45,"end":19.204},{"text":"Down...","start":19.657,"end":20.374},{"text":"it comes.","start":20.611,"end":21.448}]},"again":{"start":22.798,"end":33.359,"hold":0.8,"chunks":[{"text":"Let's try again, higher!","start":22.798,"end":24.157},{"text":"Up...","start":24.66,"end":25.278},{"text":"up...","start":25.5,"end":26.119},{"text":"up!","start":26.36,"end":26.9},{"text":"And...","start":27.13,"end":27.743},{"text":"down.","start":27.972,"end":28.674},{"text":"Every...","start":28.881,"end":29.737},{"text":"single...","start":30.732,"end":31.63},{"text":"time!","start":32.493,"end":33.309}]},"why":{"start":34.659,"end":38.412,"hold":0.8,"chunks":[{"text":"Why doesn't the ball just float away...","start":34.659,"end":36.735},{"text":"into the sky?","start":37.283,"end":38.362}]},"earth":{"start":39.712,"end":46.264,"hold":0.6,"chunks":[{"text":"Here's the secret.","start":39.712,"end":40.917},{"text":"Our Earth...","start":41.37,"end":42.22},{"text":"is enormous!","start":42.78,"end":43.785},{"text":"And it pulls everything towards it.","start":44.275,"end":46.214}]},"gravity":{"start":47.364,"end":52.345,"hold":0.8,"chunks":[{"text":"This pull has a name...","start":47.364,"end":48.712},{"text":"gravity.","start":49.242,"end":50.09},{"text":"Gravity pulls the ball down.","start":50.576,"end":52.295}]},"feel":{"start":53.645,"end":61.658,"hold":0.8,"chunks":[{"text":"You can't see gravity.","start":53.645,"end":54.979},{"text":"But you can feel it!","start":55.43,"end":56.618},{"text":"Jump up...","start":57.121,"end":57.993},{"text":"and gravity brings you back down.","start":58.616,"end":60.556},{"text":"Thump!","start":61.019,"end":61.608}]},"pulls":{"start":62.958,"end":70.948,"hold":0.6,"chunks":[{"text":"Gravity pulls the ball.","start":62.958,"end":64.394},{"text":"Gravity pulls a leaf.","start":64.773,"end":66.17},{"text":"Gravity pulls the rain.","start":66.59,"end":68.024},{"text":"Gravity pulls you...","start":68.443,"end":69.63},{"text":"and me!","start":70.167,"end":70.898}]},"feet":{"start":72.048,"end":77.369,"hold":0.6,"chunks":[{"text":"Gravity even keeps your feet on the ground, so you don't float away.","start":72.048,"end":75.691},{"text":"Thank you, gravity!","start":76.134,"end":77.319}]},"together":{"start":78.469,"end":85.892,"hold":1,"chunks":[{"text":"Gravity pulls everything, big or small.","start":78.469,"end":81.091},{"text":"A big ball and a small ball drop together...","start":81.484,"end":84.107},{"text":"and land together!","start":84.631,"end":85.842}]},"sayit":{"start":87.392,"end":94.715,"hold":1.4,"chunks":[{"text":"Say it with me...","start":87.392,"end":88.439},{"text":"Gravity pulls things down!","start":88.979,"end":90.767},{"text":"Gravity... pulls things... down!","start":92.149,"end":94.665}]},"try1":{"start":96.615,"end":103.017,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":96.615,"end":97.825},{"text":"Hold a ball in one hand, and a toy in the other...","start":98.311,"end":101.168},{"text":"at the same height.","start":101.717,"end":102.967}]},"try2":{"start":103.917,"end":109.137,"hold":1.8,"chunks":[{"text":"Let go at the same time.","start":103.917,"end":105.461},{"text":"Which one lands first?","start":105.882,"end":107.32},{"text":"Watch closely!","start":107.952,"end":109.087}]},"bye":{"start":111.437,"end":121.03,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":111.437,"end":113.154},{"text":"Remember... gravity pulls everything down to the Earth.","start":113.646,"end":116.728},{"text":"See you next time, at the Little Scientists Club!","start":117.121,"end":119.85},{"text":"Bye-bye!","start":120.269,"end":120.98}]}},"voice":"af_heart"},"ep3":{"id":"ep3","title":"Where does rain come from?","titleEnd":2.8,"duration":142.753,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.78,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Where does rain come from?","start":11.359,"end":12.73}]},"rain":{"start":13.88,"end":19.457,"hold":0.8,"chunks":[{"text":"Pitter patter, pitter patter.","start":13.88,"end":15.535},{"text":"It's raining!","start":15.96,"end":16.815},{"text":"But where was all this water... before?","start":17.294,"end":19.407}]},"sea":{"start":20.757,"end":27.027,"hold":0.6,"chunks":[{"text":"Let's find out.","start":20.757,"end":21.859},{"text":"Here is a big, blue sea.","start":22.318,"end":23.905},{"text":"And here...","start":24.329,"end":25.122},{"text":"is the warm sun.","start":25.756,"end":26.977}]},"warm":{"start":28.127,"end":34.885,"hold":0.6,"chunks":[{"text":"The sun warms the water.","start":28.127,"end":29.724},{"text":"And when water gets warm...","start":30.121,"end":31.631},{"text":"tiny bits of it float up, into the air.","start":32.254,"end":34.835}]},"vapour":{"start":35.985,"end":44.236,"hold":0.6,"chunks":[{"text":"They are so tiny, you can't see them.","start":35.985,"end":38.068},{"text":"This is called...","start":38.521,"end":39.522},{"text":"water vapour.","start":40.083,"end":41.152},{"text":"Up...","start":41.641,"end":42.26},{"text":"up...","start":42.459,"end":43.078},{"text":"up they go!","start":43.28,"end":44.186}]},"cold":{"start":45.336,"end":53.089,"hold":0.6,"chunks":[{"text":"High up in the sky, it is very cold.","start":45.336,"end":47.729},{"text":"Burr!","start":48.113,"end":48.708},{"text":"The tiny bits of water get cold...","start":49.194,"end":51.16},{"text":"and huddle together.","start":51.733,"end":53.039}]},"cloud":{"start":54.189,"end":60.294,"hold":0.8,"chunks":[{"text":"They make tiny droplets.","start":54.189,"end":55.798},{"text":"Millions of tiny droplets together make...","start":56.25,"end":58.716},{"text":"a cloud!","start":59.35,"end":60.244}]},"join":{"start":61.594,"end":68.837,"hold":0.6,"chunks":[{"text":"The droplets bump into each other, and join up.","start":61.594,"end":64.36},{"text":"They get bigger...","start":64.739,"end":65.784},{"text":"and bigger...","start":66.365,"end":67.263},{"text":"and heavier.","start":67.842,"end":68.787}]},"fall":{"start":69.937,"end":74.974,"hold":0.8,"chunks":[{"text":"When the drops get too heavy to float...","start":69.937,"end":71.981},{"text":"down they fall.","start":72.593,"end":73.634},{"text":"That's rain!","start":74.05,"end":74.924}]},"river":{"start":76.274,"end":82.549,"hold":0.8,"chunks":[{"text":"The rain fills the rivers, and the rivers run back to the sea.","start":76.274,"end":79.786},{"text":"Then the sun warms the water... again!","start":80.179,"end":82.499}]},"cycle":{"start":83.849,"end":93.634,"hold":1,"chunks":[{"text":"Up as vapour... cloud... rain...","start":83.849,"end":86.417},{"text":"back to the sea.","start":87.05,"end":88.368},{"text":"Round and round it goes.","start":88.955,"end":90.427},{"text":"We call this...","start":90.827,"end":91.819},{"text":"the water cycle!","start":92.403,"end":93.584}]},"sayit":{"start":95.134,"end":105.235,"hold":1.4,"chunks":[{"text":"Say it with me...","start":95.134,"end":96.181},{"text":"The sun lifts the water up, and the rain brings it down!","start":96.793,"end":100.222},{"text":"Sun lifts it up...","start":101.557,"end":102.804},{"text":"rain brings it down!","start":103.528,"end":105.185}]},"try1":{"start":107.135,"end":112.462,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":107.135,"end":108.345},{"text":"Ask a grown-up for a glass of very cold water, with ice.","start":108.806,"end":112.412}]},"try2":{"start":113.362,"end":126.205,"hold":1.4,"chunks":[{"text":"Leave it on the table, and","start":113.362,"end":115.045},{"text":"wait...","start":115.216,"end":115.981},{"text":"Look!","start":116.923,"end":117.567},{"text":"Little drops appear on the outside of the glass.","start":117.986,"end":120.622},{"text":"That's water vapour from the air, turning back into water.","start":121.031,"end":124.282},{"text":"Just like a tiny cloud!","start":124.683,"end":126.155}]},"bye":{"start":128.105,"end":139.353,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":128.105,"end":129.822},{"text":"Remember... the sun lifts water up to make clouds, and clouds give us rain.","start":130.256,"end":134.976},{"text":"See you next time, at the Little Scientists Club!","start":135.398,"end":138.127},{"text":"Bye-bye!","start":138.591,"end":139.303}]}},"voice":"af_heart"},"ep4":{"id":"ep4","title":"Why do I have a shadow?","titleEnd":2.8,"duration":132.788,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.865,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Why do I have a shadow?","start":11.359,"end":12.815}]},"walk":{"start":13.965,"end":21.649,"hold":0.8,"chunks":[{"text":"It's a sunny day.","start":13.965,"end":15.078},{"text":"Curie is walking...","start":15.502,"end":16.76},{"text":"and look!","start":17.364,"end":18.236},{"text":"Something dark is following Curie, on the ground.","start":18.676,"end":21.599}]},"wave":{"start":22.949,"end":31.132,"hold":0.8,"chunks":[{"text":"It's a shadow!","start":22.949,"end":23.899},{"text":"When Curie waves...","start":24.402,"end":25.665},{"text":"the shadow waves.","start":26.25,"end":27.48},{"text":"When Curie jumps...","start":27.984,"end":29.211},{"text":"the shadow jumps!","start":29.816,"end":31.082}]},"torch":{"start":32.432,"end":37.405,"hold":0.8,"chunks":[{"text":"Where does a shadow come from?","start":32.432,"end":33.957},{"text":"Let's find out...","start":34.524,"end":35.667},{"text":"with a torch.","start":36.29,"end":37.355}]},"light":{"start":38.705,"end":43.593,"hold":0.8,"chunks":[{"text":"Light travels in straight lines, like tiny, speedy arrows.","start":38.705,"end":42.459},{"text":"Zoom!","start":42.912,"end":43.543}]},"wall":{"start":44.893,"end":48.332,"hold":0.6,"chunks":[{"text":"When the light hits the wall...","start":44.893,"end":46.329},{"text":"the wall is bright.","start":46.86,"end":48.282}]},"block":{"start":49.432,"end":56.91,"hold":0.6,"chunks":[{"text":"Now Curie stands in front of the torch.","start":49.432,"end":51.612},{"text":"The light hits Curie...","start":52.063,"end":53.378},{"text":"and stops.","start":54.012,"end":54.98},{"text":"It can't go through Curie!","start":55.474,"end":56.86}]},"shadow":{"start":58.01,"end":64.115,"hold":0.8,"chunks":[{"text":"Behind Curie, no light can reach the wall.","start":58.01,"end":60.556},{"text":"That dark spot...","start":60.935,"end":62.146},{"text":"is Curie's shadow.","start":62.726,"end":64.065}]},"define":{"start":65.415,"end":68.087,"hold":1,"chunks":[{"text":"A shadow is the place where the light can't go.","start":65.415,"end":68.037}]},"lowhigh":{"start":69.587,"end":78.991,"hold":0.8,"chunks":[{"text":"Watch this!","start":69.587,"end":70.465},{"text":"When the sun is low...","start":70.896,"end":72.143},{"text":"the shadow is very, very long.","start":72.668,"end":75.119},{"text":"When the sun is high...","start":75.675,"end":76.955},{"text":"the shadow is short!","start":77.561,"end":78.941}]},"noon":{"start":80.291,"end":86.113,"hold":0.8,"chunks":[{"text":"That's why your shadow is long in the morning and evening...","start":80.291,"end":83.093},{"text":"and short at noon, when the sun is high.","start":83.633,"end":86.063}]},"sayit":{"start":87.413,"end":97.333,"hold":1.4,"chunks":[{"text":"Say it with me...","start":87.413,"end":88.46},{"text":"A shadow is where the light can't go!","start":89.072,"end":91.085},{"text":"A shadow...","start":92.421,"end":93.361},{"text":"is where the light...","start":94.085,"end":95.477},{"text":"can't go!","start":96.22,"end":97.283}]},"try1":{"start":99.233,"end":105.967,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":99.233,"end":100.443},{"text":"Ask a grown-up for a torch.","start":100.904,"end":102.62},{"text":"Make the room dark,","start":103.063,"end":104.363},{"text":"and shine it on the wall.","start":104.535,"end":105.917}]},"try2":{"start":106.867,"end":117.236,"hold":1.6,"chunks":[{"text":"Put your hand in the light.","start":106.867,"end":108.246},{"text":"Can you make a dog?","start":108.695,"end":109.938},{"text":"A bird?","start":110.5,"end":111.309},{"text":"Move your hand closer to the torch.","start":111.855,"end":113.797},{"text":"Does the shadow get bigger...","start":114.205,"end":115.71},{"text":"or smaller?","start":116.264,"end":117.186}]},"bye":{"start":119.336,"end":129.388,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":119.336,"end":121.053},{"text":"Remember... your body blocks the light, and that makes a shadow.","start":121.487,"end":125.012},{"text":"See you next time, at the Little Scientists Club!","start":125.434,"end":128.162},{"text":"Bye-bye!","start":128.627,"end":129.338}]}},"voice":"af_heart"},"ep5":{"id":"ep5","title":"Why do boats float?","titleEnd":2.8,"duration":130.64,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.783,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Why do boats float?","start":11.359,"end":12.733}]},"stone":{"start":13.883,"end":21.636,"hold":0.8,"chunks":[{"text":"Here's a big pond.","start":13.883,"end":15.167},{"text":"Splash!","start":15.591,"end":16.366},{"text":"Curie drops in a stone.","start":16.845,"end":18.294},{"text":"Down...","start":18.696,"end":19.413},{"text":"it goes.","start":19.634,"end":20.5},{"text":"It sinks.","start":20.737,"end":21.586}]},"boat":{"start":22.936,"end":28.079,"hold":0.8,"chunks":[{"text":"Now Curie puts in a little toy boat.","start":22.936,"end":25.023},{"text":"It stays on top.","start":25.483,"end":26.754},{"text":"It floats!","start":27.177,"end":28.029}]},"why":{"start":29.379,"end":32.655,"hold":0.8,"chunks":[{"text":"Why does the stone sink...","start":29.379,"end":30.812},{"text":"but the boat floats?","start":31.36,"end":32.605}]},"push":{"start":33.955,"end":42.92,"hold":0.8,"chunks":[{"text":"Here's the secret...","start":33.955,"end":35.222},{"text":"water pushes up!","start":35.848,"end":37.183},{"text":"Try pushing a ball under the water in the bath.","start":37.628,"end":40.141},{"text":"Can you feel the water pushing it back up?","start":40.588,"end":42.87}]},"displace":{"start":44.22,"end":51.052,"hold":0.8,"chunks":[{"text":"When something sits in water, it pushes some water out of the way.","start":44.22,"end":47.86},{"text":"And the water...","start":48.244,"end":49.202},{"text":"pushes back up!","start":49.815,"end":51.002}]},"stone2":{"start":52.352,"end":61.737,"hold":0.8,"chunks":[{"text":"The stone is small, and heavy.","start":52.352,"end":54.236},{"text":"It pushes only a little water away...","start":54.687,"end":56.918},{"text":"so the water's push is too small.","start":57.552,"end":59.436},{"text":"Down...","start":59.93,"end":60.647},{"text":"it sinks.","start":60.869,"end":61.687}]},"boat2":{"start":63.037,"end":72.504,"hold":0.8,"chunks":[{"text":"The boat is wide, and hollow, full of air.","start":63.037,"end":65.544},{"text":"It pushes a lot of water away!","start":65.923,"end":67.685},{"text":"So the water pushes up hard, and holds the boat up.","start":68.145,"end":71.183},{"text":"It floats!","start":71.603,"end":72.454}]},"clay1":{"start":73.804,"end":79.732,"hold":0.8,"chunks":[{"text":"Let's test it.","start":73.804,"end":74.878},{"text":"Curie squashes some clay into a ball.","start":75.321,"end":77.359},{"text":"Plop!","start":77.739,"end":78.392},{"text":"It sinks.","start":78.864,"end":79.682}]},"clay2":{"start":81.032,"end":89.112,"hold":1,"chunks":[{"text":"Now Curie makes the same clay into a wide boat shape...","start":81.032,"end":84.342},{"text":"It floats!","start":85.185,"end":86.091},{"text":"Same clay...","start":86.506,"end":87.42},{"text":"different shape!","start":87.996,"end":89.062}]},"sayit":{"start":90.612,"end":96.894,"hold":1.4,"chunks":[{"text":"Say it with me...","start":90.612,"end":91.659},{"text":"Water pushes up!","start":92.199,"end":93.572},{"text":"Water... pushes... up!","start":94.954,"end":96.844}]},"try1":{"start":98.794,"end":107.678,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":98.794,"end":100.004},{"text":"Ask a grown-up for a bowl of water.","start":100.49,"end":102.471},{"text":"Collect a spoon, a coin, a cork, a plastic lid...","start":102.869,"end":106.1},{"text":"and a leaf.","start":106.718,"end":107.628}]},"try2":{"start":108.578,"end":114.905,"hold":1.8,"chunks":[{"text":"Guess first...","start":108.578,"end":109.617},{"text":"will it sink, or float?","start":110.199,"end":111.737},{"text":"Then drop it in.","start":112.222,"end":113.414},{"text":"Were you right?","start":113.865,"end":114.855}]},"bye":{"start":117.205,"end":127.24,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":117.205,"end":118.922},{"text":"Remember... water pushes up, and that is why boats float.","start":119.414,"end":122.938},{"text":"See you next time, at the Little Scientists Club!","start":123.331,"end":126.059},{"text":"Bye-bye!","start":126.478,"end":127.19}]}},"voice":"af_heart"},"ep6":{"id":"ep6","title":"What makes things happen?","titleEnd":2.8,"duration":162.548,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.857,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"What makes things happen?","start":11.359,"end":12.807}]},"seed":{"start":13.957,"end":21.48,"hold":0.8,"chunks":[{"text":"Curie has a tiny seed...","start":13.957,"end":15.588},{"text":"and Curie wants a flower!","start":16.174,"end":17.791},{"text":"But a seed on its own...","start":18.27,"end":19.666},{"text":"just sits there.","start":20.222,"end":21.43}]},"pieces":{"start":22.78,"end":29.816,"hold":0.6,"chunks":[{"text":"A flower needs lots of pieces.","start":22.78,"end":24.814},{"text":"Soil!","start":25.274,"end":25.916},{"text":"A seed!","start":26.38,"end":27.134},{"text":"Water!","start":27.637,"end":28.282},{"text":"And sunshine!","start":28.762,"end":29.766}]},"pie":{"start":30.916,"end":37.194,"hold":0.8,"chunks":[{"text":"Each piece is a slice of Curie's cause pie.","start":30.916,"end":33.449},{"text":"When the pie is full...","start":33.846,"end":35.152},{"text":"something will happen!","start":35.775,"end":37.144}]},"wait":{"start":38.494,"end":46.001,"hold":0.6,"chunks":[{"text":"Now... we wait.","start":38.494,"end":39.758},{"text":"Causes take time.","start":40.211,"end":41.594},{"text":"One day...","start":42,"end":42.838},{"text":"two days...","start":43.455,"end":44.405},{"text":"three days...","start":44.932,"end":45.951}]},"grow":{"start":47.101,"end":55.416,"hold":1,"chunks":[{"text":"Pop!","start":47.101,"end":47.706},{"text":"A little sprout!","start":48.127,"end":49.163},{"text":"And...","start":49.649,"end":50.262},{"text":"a flower!","start":50.835,"end":51.718},{"text":"All the pieces together...","start":52.198,"end":53.63},{"text":"made it happen!","start":54.265,"end":55.366}]},"test":{"start":56.916,"end":64.517,"hold":0.7,"chunks":[{"text":"Which pieces really matter?","start":56.916,"end":58.459},{"text":"Scientists test it!","start":59.104,"end":60.479},{"text":"Take one piece away...","start":60.982,"end":62.412},{"text":"and see what happens.","start":63.035,"end":64.467}]},"nowater":{"start":65.717,"end":74.113,"hold":0.8,"chunks":[{"text":"No water?","start":65.717,"end":66.636},{"text":"Nothing grows.","start":67.577,"end":68.682},{"text":"No flower!","start":69.102,"end":70.02},{"text":"Water makes a difference...","start":70.48,"end":72.025},{"text":"so water is a cause.","start":72.562,"end":74.063}]},"nosun":{"start":75.413,"end":82.828,"hold":0.8,"chunks":[{"text":"No sunshine?","start":75.413,"end":76.562},{"text":"Just a tiny, white sprout.","start":77.595,"end":79.426},{"text":"No flower!","start":79.806,"end":80.724},{"text":"Sunshine is a cause too.","start":81.197,"end":82.778}]},"teddy":{"start":84.128,"end":89.278,"hold":0.6,"chunks":[{"text":"Hmm.","start":84.128,"end":84.675},{"text":"Teddy sat next to the pot all week.","start":85.068,"end":87.15},{"text":"Did teddy make the flower grow?","start":87.529,"end":89.228}]},"teddytest":{"start":90.378,"end":98.497,"hold":0.9,"chunks":[{"text":"Let's test!","start":90.378,"end":91.325},{"text":"Take teddy away...","start":91.753,"end":92.978},{"text":"the flower still grows!","start":93.585,"end":95.152},{"text":"Teddy is not a cause.","start":95.591,"end":96.965},{"text":"It was just there!","start":97.388,"end":98.447}]},"rule":{"start":99.897,"end":106.865,"hold":0.9,"chunks":[{"text":"So... to make something happen, you need all the pieces.","start":99.897,"end":103.097},{"text":"To stop it...","start":103.54,"end":104.557},{"text":"just take one piece away!","start":105.107,"end":106.815}]},"hands":{"start":108.265,"end":118.429,"hold":0.8,"chunks":[{"text":"Doctors use this trick!","start":108.265,"end":109.701},{"text":"Germs on your hands and fingers in your mouth can make a tummy ache.","start":110.162,"end":114.044},{"text":"Wash the germs away...","start":114.486,"end":115.97},{"text":"and that tummy ache can't happen!","start":116.593,"end":118.379}]},"sayit":{"start":119.729,"end":127.826,"hold":1.4,"chunks":[{"text":"Say it with me...","start":119.729,"end":120.776},{"text":"Lots of pieces make it happen!","start":121.397,"end":123.217},{"text":"Lots of pieces...","start":124.548,"end":125.89},{"text":"make it happen!","start":126.509,"end":127.776}]},"try1":{"start":129.726,"end":137.647,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":129.726,"end":130.936},{"text":"Ask a grown-up for two cups, cotton wool...","start":131.371,"end":133.745},{"text":"and two bean seeds.","start":134.327,"end":135.744},{"text":"Put a seed in each cup.","start":136.209,"end":137.597}]},"try2":{"start":138.547,"end":147.412,"hold":1.6,"chunks":[{"text":"Water one cup every day.","start":138.547,"end":140.208},{"text":"Keep the other one dry.","start":140.61,"end":142.105},{"text":"Wait a few days.","start":142.528,"end":143.735},{"text":"Which one grows?","start":144.129,"end":145.355},{"text":"Which piece was missing?","start":145.903,"end":147.362}]},"bye":{"start":149.512,"end":159.148,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":149.512,"end":151.229},{"text":"Remember... lots of pieces together make things happen.","start":151.703,"end":154.743},{"text":"See you next time, at the Little Scientists Club!","start":155.164,"end":157.892},{"text":"Bye-bye!","start":158.387,"end":159.098}]}},"voice":"af_heart"},"ep7":{"id":"ep7","title":"Why do magnets stick?","titleEnd":2.8,"duration":151.429,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.832,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Why do magnets stick?","start":11.359,"end":12.782}]},"fridge":{"start":13.932,"end":22.117,"hold":0.6,"chunks":[{"text":"Look!","start":13.932,"end":14.515},{"text":"Curie made a drawing.","start":14.979,"end":16.194},{"text":"She puts it on the fridge...","start":16.631,"end":18.058},{"text":"with a magnet.","start":18.614,"end":19.66},{"text":"Click!","start":20.121,"end":20.74},{"text":"It sticks!","start":21.237,"end":22.067}]},"door":{"start":23.217,"end":29.978,"hold":0.8,"chunks":[{"text":"Now Curie tries the magnet on the wooden door...","start":23.217,"end":25.771},{"text":"It does not stick!","start":26.406,"end":27.621},{"text":"It falls off,","start":28.086,"end":29.1},{"text":"plop!","start":29.275,"end":29.928}]},"why":{"start":31.278,"end":36.93,"hold":0.8,"chunks":[{"text":"Why does a magnet stick to some things...","start":31.278,"end":33.546},{"text":"but not to others?","start":34.094,"end":35.285},{"text":"Let's find out!","start":35.779,"end":36.88}]},"clip":{"start":38.23,"end":44.483,"hold":0.5,"chunks":[{"text":"Scientists test it!","start":38.23,"end":39.604},{"text":"Here is a paper clip...","start":40.101,"end":41.43},{"text":"Zip!","start":41.991,"end":42.63},{"text":"The magnet pulls it.","start":43.12,"end":44.433}]},"nothing":{"start":45.483,"end":51.245,"hold":0.6,"chunks":[{"text":"A pencil... nothing.","start":45.483,"end":47.061},{"text":"A leaf... nothing.","start":47.445,"end":48.838},{"text":"A plastic block... nothing.","start":49.282,"end":51.195}]},"iron":{"start":52.345,"end":58.03,"hold":0.9,"chunks":[{"text":"The paper clip has...","start":52.345,"end":53.721},{"text":"iron in it!","start":54.344,"end":55.397},{"text":"Magnets pull things with iron in them.","start":55.9,"end":57.98}]},"foil":{"start":59.43,"end":67.53,"hold":0.9,"chunks":[{"text":"Kitchen foil is shiny metal too...","start":59.43,"end":61.546},{"text":"but the magnet does not pull it!","start":62.069,"end":63.844},{"text":"Magnets pull iron...","start":64.304,"end":65.715},{"text":"not every metal.","start":66.294,"end":67.48}]},"gap":{"start":68.93,"end":76.512,"hold":0.8,"chunks":[{"text":"A magnet can pull a paper clip...","start":68.93,"end":70.787},{"text":"without even touching it!","start":71.399,"end":72.946},{"text":"The pull is invisible.","start":73.362,"end":74.789},{"text":"We cannot see it!","start":75.22,"end":76.462}]},"ends":{"start":77.812,"end":82.472,"hold":0.5,"chunks":[{"text":"Every magnet has two ends.","start":77.812,"end":79.467},{"text":"A red end...","start":79.86,"end":80.842},{"text":"and a blue end.","start":81.366,"end":82.422}]},"pull":{"start":83.472,"end":89.824,"hold":0.5,"chunks":[{"text":"Watch!","start":83.472,"end":84.146},{"text":"A red end and a blue end come close...","start":84.574,"end":86.854},{"text":"Click!","start":87.462,"end":88.152},{"text":"They pull together.","start":88.59,"end":89.774}]},"push":{"start":90.824,"end":98.146,"hold":0.9,"chunks":[{"text":"Now turn one around.","start":90.824,"end":92.215},{"text":"Red and red...","start":92.659,"end":93.724},{"text":"they push apart!","start":94.273,"end":95.511},{"text":"The same ends push each other away.","start":96.001,"end":98.096}]},"home":{"start":99.546,"end":109.24,"hold":0.8,"chunks":[{"text":"Now we know why!","start":99.546,"end":100.577},{"text":"The fridge door has iron in it...","start":101.038,"end":102.976},{"text":"so the magnet sticks.","start":103.588,"end":104.979},{"text":"Wood has no iron in it...","start":105.473,"end":107.123},{"text":"so the magnet falls off.","start":107.646,"end":109.19}]},"sayit":{"start":110.54,"end":116.968,"hold":1.4,"chunks":[{"text":"Say it with me...","start":110.54,"end":111.587},{"text":"Magnets pull iron!","start":112.208,"end":113.631},{"text":"Magnets... pull... iron!","start":114.962,"end":116.918}]},"try1":{"start":118.868,"end":127.179,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":118.868,"end":120.078},{"text":"Ask a grown-up for a fridge magnet.","start":120.513,"end":122.576},{"text":"Find a paper clip, a pencil, a leaf...","start":122.998,"end":125.474},{"text":"and some foil.","start":126.059,"end":127.129}]},"try2":{"start":128.079,"end":136.483,"hold":1.6,"chunks":[{"text":"Guess first...","start":128.079,"end":129.118},{"text":"will it stick?","start":129.674,"end":130.637},{"text":"Then test it.","start":131.099,"end":132.19},{"text":"Keep magnets out of your mouth!","start":132.584,"end":134.242},{"text":"Which things does the magnet pull?","start":134.662,"end":136.433}]},"bye":{"start":138.583,"end":148.029,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":138.583,"end":140.3},{"text":"Remember... magnets pull things with iron in them.","start":140.774,"end":143.624},{"text":"See you next time, at the Little Scientists Club!","start":144.044,"end":146.773},{"text":"Bye-bye!","start":147.267,"end":147.979}]}},"voice":"af_heart"},"ep8":{"id":"ep8","title":"How do we hear sounds?","titleEnd":2.8,"duration":142.942,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.753,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"How do we hear sounds?","start":11.359,"end":12.703}]},"twang":{"start":13.853,"end":20.67,"hold":0.8,"chunks":[{"text":"Curie has a box guitar.","start":13.853,"end":15.562},{"text":"Listen...","start":15.986,"end":16.748},{"text":"Twang!","start":17.353,"end":18.03},{"text":"Where does that sound come from?","start":18.971,"end":20.62}]},"closer":{"start":21.97,"end":25.208,"hold":0.4,"chunks":[{"text":"Let's look closer.","start":21.97,"end":23.263},{"text":"Much... much closer!","start":23.722,"end":25.158}]},"string":{"start":26.108,"end":32.125,"hold":1,"chunks":[{"text":"Look at the string!","start":26.108,"end":27.121},{"text":"It is wiggling...","start":27.555,"end":28.641},{"text":"back and forth...","start":29.264,"end":30.406},{"text":"super fast!","start":30.952,"end":32.075}]},"wiggle":{"start":33.625,"end":39.227,"hold":0.8,"chunks":[{"text":"When something wiggles like that...","start":33.625,"end":35.395},{"text":"it makes a sound.","start":36.02,"end":37.186},{"text":"Sounds are made by wiggles!","start":37.63,"end":39.177}]},"air":{"start":40.527,"end":51.311,"hold":0.8,"chunks":[{"text":"The wiggle pushes the air...","start":40.527,"end":42.081},{"text":"and the air passes it along.","start":42.611,"end":44.307},{"text":"Push...","start":44.793,"end":45.489},{"text":"push...","start":46.062,"end":46.806},{"text":"push...","start":47.412,"end":48.156},{"text":"all the way...","start":48.841,"end":49.782},{"text":"to your ear!","start":50.366,"end":51.261}]},"ear":{"start":52.611,"end":58.954,"hold":0.8,"chunks":[{"text":"Inside your ear is a tiny drum.","start":52.611,"end":54.755},{"text":"The wiggle makes it wiggle too...","start":55.206,"end":56.977},{"text":"and you hear the sound!","start":57.611,"end":58.904}]},"feel":{"start":60.254,"end":68.313,"hold":1,"chunks":[{"text":"You can feel a wiggle!","start":60.254,"end":61.511},{"text":"Gently put your fingers on your throat...","start":61.926,"end":63.933},{"text":"and hum.","start":64.514,"end":65.31},{"text":"Hmmm.","start":65.769,"end":66.446},{"text":"Can you feel it buzz?","start":66.928,"end":68.263}]},"test":{"start":69.813,"end":73.546,"hold":0.4,"chunks":[{"text":"Scientists test it!","start":69.813,"end":71.189},{"text":"Let's put some rice on a drum.","start":71.674,"end":73.496}]},"soft":{"start":74.446,"end":81.361,"hold":0.6,"chunks":[{"text":"A tiny tap...","start":74.446,"end":75.56},{"text":"makes tiny wiggles.","start":76.103,"end":77.496},{"text":"The rice hops a little...","start":77.912,"end":79.302},{"text":"and the sound is quiet.","start":79.878,"end":81.311}]},"loud":{"start":82.461,"end":89.277,"hold":0.8,"chunks":[{"text":"A big bang...","start":82.461,"end":83.413},{"text":"makes big wiggles!","start":83.953,"end":85.252},{"text":"The rice jumps way up...","start":85.734,"end":87.295},{"text":"and the sound is loud!","start":87.848,"end":89.227}]},"highlow":{"start":90.577,"end":101.384,"hold":1,"chunks":[{"text":"Now let's change how fast it wiggles.","start":90.577,"end":92.839},{"text":"A short string wiggles faster...","start":93.282,"end":95.125},{"text":"and makes a high sound.","start":95.675,"end":97.051},{"text":"A long string wiggles slower...","start":97.541,"end":99.288},{"text":"and makes a low sound.","start":99.922,"end":101.334}]},"sayit":{"start":102.884,"end":108.96,"hold":1.4,"chunks":[{"text":"Say it with me...","start":102.884,"end":103.931},{"text":"Sounds are wiggles!","start":104.513,"end":105.749},{"text":"Sounds... are... wiggles!","start":107.134,"end":108.91}]},"try1":{"start":110.86,"end":116.922,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":110.86,"end":112.07},{"text":"Ask a grown-up to stretch a rubber band...","start":112.562,"end":114.836},{"text":"over an open box.","start":115.378,"end":116.872}]},"try2":{"start":117.822,"end":128.71,"hold":1.6,"chunks":[{"text":"Pluck it gently...","start":117.822,"end":118.99},{"text":"away from your face.","start":119.538,"end":120.856},{"text":"Can you see it wiggle?","start":121.318,"end":122.576},{"text":"Now stretch it tighter, with your grown-up.","start":123.182,"end":125.494},{"text":"Is the sound higher...","start":125.876,"end":127.218},{"text":"or lower?","start":127.782,"end":128.66}]},"bye":{"start":130.81,"end":139.542,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":130.81,"end":132.527},{"text":"Remember... sounds are made by wiggles.","start":132.968,"end":135.199},{"text":"See you next time, at the Little Scientists Club!","start":135.621,"end":138.349},{"text":"Bye-bye!","start":138.781,"end":139.492}]}},"voice":"af_heart"},"ep9":{"id":"ep9","title":"Why is it dark at night?","titleEnd":2.8,"duration":142.039,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":13.019,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Why is it dark at night?","start":11.359,"end":12.969}]},"evening":{"start":14.119,"end":21.4,"hold":0.9,"chunks":[{"text":"It's evening.","start":14.119,"end":14.989},{"text":"The sun goes down...","start":15.413,"end":16.668},{"text":"and down...","start":17.272,"end":18.164},{"text":"and it gets dark.","start":18.72,"end":19.98},{"text":"Good night!","start":20.441,"end":21.35}]},"morning":{"start":22.8,"end":27.175,"hold":0.8,"chunks":[{"text":"In the morning...","start":22.8,"end":23.738},{"text":"the sun comes up again.","start":24.372,"end":25.795},{"text":"Good morning!","start":26.26,"end":27.125}]},"why":{"start":28.475,"end":34.332,"hold":0.6,"chunks":[{"text":"Does the sun go to sleep at night?","start":28.475,"end":30.35},{"text":"Let's fly up into space...","start":30.917,"end":32.51},{"text":"and find out!","start":33.133,"end":34.282}]},"earth":{"start":35.432,"end":42.961,"hold":0.8,"chunks":[{"text":"Here is our Earth, a giant ball.","start":35.432,"end":37.462},{"text":"And here is the sun.","start":37.915,"end":39.136},{"text":"The sun doesn't go to sleep.","start":39.542,"end":41.197},{"text":"It keeps on shining!","start":41.644,"end":42.911}]},"half":{"start":44.261,"end":52.144,"hold":0.6,"chunks":[{"text":"The sun can only shine on one side of the Earth.","start":44.261,"end":46.91},{"text":"That side has day.","start":47.294,"end":48.53},{"text":"The other side is dark...","start":48.974,"end":50.502},{"text":"it has night.","start":51.075,"end":52.094}]},"spin":{"start":53.244,"end":57.54,"hold":0.5,"chunks":[{"text":"And our Earth is always spinning...","start":53.244,"end":54.998},{"text":"slowly, round and round.","start":55.621,"end":57.49}]},"house":{"start":58.54,"end":63.721,"hold":0.6,"chunks":[{"text":"Look... here's Curie's house!","start":58.54,"end":60.175},{"text":"Right now it faces the sun.","start":60.59,"end":62.234},{"text":"It's daytime!","start":62.654,"end":63.671}]},"turn":{"start":64.821,"end":73.897,"hold":0.9,"chunks":[{"text":"The Earth turns...","start":64.821,"end":65.916},{"text":"and turns.","start":66.528,"end":67.487},{"text":"Now Curie's house faces away from the sun.","start":67.903,"end":70.682},{"text":"It's night!","start":71.113,"end":71.929},{"text":"The sun is still shining.","start":72.412,"end":73.847}]},"oneday":{"start":75.297,"end":80.897,"hold":0.7,"chunks":[{"text":"One whole spin takes one day...","start":75.297,"end":77.18},{"text":"and one night.","start":77.723,"end":78.822},{"text":"Then it starts all over again!","start":79.238,"end":80.847}]},"other":{"start":82.097,"end":87.115,"hold":1,"chunks":[{"text":"So when it's day for you...","start":82.097,"end":83.526},{"text":"it's night for children on the other side of the world!","start":84.065,"end":87.065}]},"sky":{"start":88.615,"end":98.485,"hold":1,"chunks":[{"text":"In the garden, the sun seems to come up...","start":88.615,"end":90.93},{"text":"and go down.","start":91.542,"end":92.585},{"text":"But the sun isn't really going up and down.","start":93.021,"end":95.484},{"text":"We are turning!","start":95.932,"end":96.829},{"text":"The Earth spins.","start":97.332,"end":98.435}]},"sayit":{"start":99.985,"end":105.81,"hold":1.4,"chunks":[{"text":"Say it with me...","start":99.985,"end":101.032},{"text":"The Earth spins!","start":101.614,"end":102.817},{"text":"The Earth... spins!","start":104.202,"end":105.76}]},"try1":{"start":107.71,"end":115.056,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":107.71,"end":108.92},{"text":"Ask a grown-up for a torch and a ball.","start":109.412,"end":111.559},{"text":"Put a sticker on the ball...","start":111.952,"end":113.362},{"text":"that's your house.","start":113.89,"end":115.006}]},"try2":{"start":115.956,"end":126.62,"hold":1.6,"chunks":[{"text":"Make the room dark.","start":115.956,"end":117.273},{"text":"Shine the torch on the ball...","start":117.669,"end":119.194},{"text":"never in eyes!","start":119.776,"end":120.973},{"text":"Turn the ball slowly.","start":121.438,"end":122.773},{"text":"When is it day at your house?","start":123.155,"end":124.767},{"text":"When is it night?","start":125.35,"end":126.57}]},"bye":{"start":128.72,"end":138.639,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":128.72,"end":130.437},{"text":"Remember... the Earth spins, and that makes day and night.","start":130.878,"end":134.295},{"text":"See you next time, at the Little Scientists Club!","start":134.718,"end":137.446},{"text":"Bye-bye!","start":137.878,"end":138.589}]}},"voice":"af_heart"},"ep10":{"id":"ep10","title":"Where does the sugar go?","titleEnd":2.8,"duration":138.594,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":12.805,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Where does the sugar go?","start":11.359,"end":12.755}]},"stir":{"start":13.905,"end":19.573,"hold":0.5,"chunks":[{"text":"Curie is making lemonade!","start":13.905,"end":15.6},{"text":"In goes a spoon of sugar.","start":16.064,"end":17.612},{"text":"Stir... stir... stir!","start":18.05,"end":19.523}]},"gone":{"start":20.573,"end":24.341,"hold":1,"chunks":[{"text":"Look!","start":20.573,"end":21.156},{"text":"The sugar is gone!","start":21.659,"end":22.84},{"text":"Where did it go?","start":23.304,"end":24.291}]},"taste":{"start":25.841,"end":31.982,"hold":0.8,"chunks":[{"text":"Curie tastes a drop...","start":25.841,"end":27.247},{"text":"Yum!","start":27.794,"end":28.432},{"text":"It's sweet!","start":28.926,"end":29.75},{"text":"So the sugar must still be there.","start":30.183,"end":31.932}]},"closer":{"start":33.282,"end":38.329,"hold":0.8,"chunks":[{"text":"But why can't we see it?","start":33.282,"end":34.543},{"text":"Let's look closer.","start":35.191,"end":36.449},{"text":"Much... much closer.","start":36.855,"end":38.279}]},"bits":{"start":39.629,"end":45.022,"hold":0.5,"chunks":[{"text":"A grain of sugar is made of tiny, tiny bits.","start":39.629,"end":42.786},{"text":"Just like ice cream, remember?","start":43.171,"end":44.972}]},"spread":{"start":46.022,"end":52.68,"hold":0.6,"chunks":[{"text":"The water bits pull the sugar bits apart.","start":46.022,"end":48.368},{"text":"Then the sugar bits spread out...","start":48.819,"end":50.604},{"text":"between the water bits.","start":51.239,"end":52.63}]},"dissolve":{"start":53.78,"end":58.674,"hold":1.2,"chunks":[{"text":"Now they are too tiny to see.","start":53.78,"end":55.45},{"text":"We say...","start":55.829,"end":56.628},{"text":"the sugar dissolves!","start":57.209,"end":58.624}]},"notmelt":{"start":60.374,"end":67.972,"hold":1,"chunks":[{"text":"Dissolving is not melting!","start":60.374,"end":62.021},{"text":"Melting needs heat, like the sun.","start":62.506,"end":64.543},{"text":"Dissolving is tiny bits spreading out, in water.","start":64.922,"end":67.922}]},"test":{"start":69.472,"end":74.65,"hold":0.5,"chunks":[{"text":"Scientists test it!","start":69.472,"end":70.846},{"text":"Does everything dissolve?","start":71.277,"end":72.848},{"text":"Let's try sand.","start":73.39,"end":74.6}]},"sand":{"start":75.65,"end":82.042,"hold":1,"chunks":[{"text":"Stir... stir...","start":75.65,"end":76.814},{"text":"The sand sinks to the bottom, and stays there.","start":77.354,"end":80.139},{"text":"Sand doesn't dissolve!","start":80.622,"end":81.992}]},"salt":{"start":83.542,"end":91.552,"hold":1,"chunks":[{"text":"Salt dissolves too.","start":83.542,"end":84.914},{"text":"And if the salty water dries up in the sun...","start":85.357,"end":87.777},{"text":"the salt comes back!","start":88.327,"end":89.694},{"text":"It was there all along.","start":90.184,"end":91.502}]},"sayit":{"start":93.052,"end":100.66,"hold":1.4,"chunks":[{"text":"So where did the sugar go?","start":93.052,"end":94.508},{"text":"Say it with me...","start":95.109,"end":96.157},{"text":"It's still there!","start":96.768,"end":97.789},{"text":"It's still... there!","start":99.183,"end":100.61}]},"try1":{"start":102.56,"end":109.746,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":102.56,"end":103.77},{"text":"Ask a grown-up for two glasses of water, a spoon of sugar...","start":104.262,"end":107.787},{"text":"and a spoon of sand.","start":108.329,"end":109.696}]},"try2":{"start":110.646,"end":116.583,"hold":0.8,"chunks":[{"text":"Stir the sugar into one glass...","start":110.646,"end":112.551},{"text":"and the sand into the other.","start":113.099,"end":114.642},{"text":"Which one disappears?","start":115.104,"end":116.533}]},"try3":{"start":117.883,"end":123.791,"hold":1.6,"chunks":[{"text":"Taste only the sugar water, and only if your grown-up says yes.","start":117.883,"end":121.872},{"text":"Is the sugar still there?","start":122.275,"end":123.741}]},"bye":{"start":125.891,"end":135.194,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":125.891,"end":127.608},{"text":"Remember... when sugar dissolves, it's still there.","start":128.082,"end":130.789},{"text":"See you next time, at the Little Scientists Club!","start":131.21,"end":133.938},{"text":"Bye-bye!","start":134.433,"end":135.144}]}},"voice":"af_heart"},"ep11":{"id":"ep11","title":"Why do rolling things stop?","titleEnd":2.8,"duration":137.595,"lines":{"hello":{"start":3.05,"end":8.601,"hold":0.3,"chunks":[{"text":"Hello, little scientists!","start":3.05,"end":4.581},{"text":"I'm Curie!","start":5.033,"end":5.875},{"text":"Welcome... to the Little Scientists Club!","start":6.355,"end":8.551}]},"q":{"start":9.401,"end":13.091,"hold":0.6,"chunks":[{"text":"Today's big question...","start":9.401,"end":10.787},{"text":"Why do rolling things stop?","start":11.359,"end":13.041}]},"roll":{"start":14.191,"end":24.067,"hold":0.8,"chunks":[{"text":"Curie rolls her toy car across the floor.","start":14.191,"end":16.673},{"text":"Wheee!","start":17.097,"end":17.679},{"text":"It rolls...","start":18.158,"end":19.051},{"text":"and rolls...","start":19.607,"end":20.561},{"text":"and slows down...","start":21.142,"end":22.424},{"text":"and stops.","start":23.049,"end":24.017}]},"why":{"start":25.367,"end":30.151,"hold":0.8,"chunks":[{"text":"Why did it stop?","start":25.367,"end":26.46},{"text":"Nobody grabbed it!","start":27.116,"end":28.344},{"text":"Let's look closer.","start":28.809,"end":30.101}]},"rub":{"start":31.451,"end":40.175,"hold":0.5,"chunks":[{"text":"Here's the secret...","start":31.451,"end":32.772},{"text":"The wheels rub on the floor, as they roll.","start":33.32,"end":35.851},{"text":"The rubbing pulls back on the car...","start":36.345,"end":38.231},{"text":"and slows it down.","start":38.777,"end":40.125}]},"name":{"start":41.175,"end":44.365,"hold":0.8,"chunks":[{"text":"Scientists call this...","start":41.175,"end":42.569},{"text":"rubbing friction.","start":43.194,"end":44.315}]},"test":{"start":45.665,"end":51.923,"hold":0.5,"chunks":[{"text":"Scientists test it!","start":45.665,"end":47.039},{"text":"Same ramp...","start":47.46,"end":48.409},{"text":"same car...","start":49.022,"end":50.005},{"text":"but different floors.","start":50.578,"end":51.873}]},"carpet":{"start":52.923,"end":58.25,"hold":0.6,"chunks":[{"text":"On bumpy carpet...","start":52.923,"end":54.283},{"text":"there is lots of rubbing.","start":54.907,"end":56.314},{"text":"The car stops quickly!","start":56.817,"end":58.2}]},"floor":{"start":59.35,"end":64.571,"hold":0.6,"chunks":[{"text":"On a smooth wooden floor...","start":59.35,"end":60.876},{"text":"there is less rubbing.","start":61.399,"end":62.73},{"text":"The car rolls further.","start":63.19,"end":64.521}]},"ice":{"start":65.671,"end":73.461,"hold":1,"chunks":[{"text":"On slippery ice...","start":65.671,"end":66.921},{"text":"there is hardly any rubbing!","start":67.532,"end":69.096},{"text":"The car rolls a long, long way...","start":69.511,"end":71.58},{"text":"before it stops.","start":72.175,"end":73.411}]},"grip":{"start":74.961,"end":80.706,"hold":0.4,"chunks":[{"text":"And friction is useful, too!","start":74.961,"end":76.61},{"text":"It helps your shoes grip the ground...","start":77.041,"end":78.944},{"text":"so you don't slip.","start":79.469,"end":80.656}]},"slip":{"start":81.606,"end":88.004,"hold":0.6,"chunks":[{"text":"But on slippery ice...","start":81.606,"end":82.983},{"text":"Whoops!","start":83.523,"end":84.294},{"text":"There is hardly any rubbing, so Curie slips and slides!","start":84.776,"end":87.954}]},"brakes":{"start":89.104,"end":94.645,"hold":0.6,"chunks":[{"text":"Bike brakes use rubbing, too.","start":89.104,"end":90.9},{"text":"They rub the wheel...","start":91.343,"end":92.567},{"text":"to slow the bike down.","start":93.117,"end":94.595}]},"sayit":{"start":95.745,"end":102.556,"hold":1.4,"chunks":[{"text":"Say it with me...","start":95.745,"end":96.792},{"text":"Rubbing slows it down!","start":97.374,"end":98.947},{"text":"Rubbing... slows it... down!","start":100.332,"end":102.506}]},"try1":{"start":104.456,"end":111.36,"hold":0.4,"chunks":[{"text":"Let's try it at home!","start":104.456,"end":105.666},{"text":"Ask a grown-up to help you make a ramp, with a big book.","start":106.158,"end":109.337},{"text":"Roll a toy car down it.","start":109.73,"end":111.31}]},"try2":{"start":112.26,"end":123.294,"hold":1.6,"chunks":[{"text":"Where does it stop on the floor?","start":112.26,"end":113.943},{"text":"Put a block there!","start":114.51,"end":115.598},{"text":"Now lay a towel at the bottom...","start":116.06,"end":117.829},{"text":"and roll the car again, from the same spot.","start":118.415,"end":121.102},{"text":"Where does it stop... now?","start":121.52,"end":123.244}]},"bye":{"start":125.394,"end":134.195,"hold":1.2,"chunks":[{"text":"Great job, little scientist!","start":125.394,"end":127.111},{"text":"Remember... rubbing slows things down.","start":127.552,"end":129.851},{"text":"See you next time, at the Little Scientists Club!","start":130.274,"end":133.002},{"text":"Bye-bye!","start":133.433,"end":134.145}]}},"voice":"af_heart"}},"meta":{"ep1":{"title":"Why does ice cream melt?","hint":"Drag the sun close to the ice cream to melt it. Tap the freezer to make it hard again.","cues":{"melt":"The sun is warm! Heat makes the ice cream melt.","cold":"Brrr! The freezer is cold. The ice cream is hard again."}},"ep2":{"title":"Why does a ball always come down?","hint":"Drag the ball and let go to throw it. Try to make it float away — you can't! Tap the big and small balls to drop them together.","cues":{"down":"Up it goes... and down it comes. Gravity pulls it down every time!","together":"Big ball and small ball land together!"}},"ep3":{"title":"Where does rain come from?","hint":"Drag the sun down to warm the sea and lift the water up. When the cloud gets heavy, tap it to make rain!","cues":{"warm":"The sun warms the sea. Tiny bits of water float up!","heavy":"The cloud is heavy now. Tap it!"}},"ep4":{"title":"Why do I have a shadow?","hint":"Drag the sun across the sky and watch Curie's shadow stretch and shrink. Drag Curie too!","cues":{"low":"The sun is low, so the shadow is long!","high":"The sun is high, so the shadow is short!"}},"ep5":{"title":"Why do boats float?","hint":"Guess first, then drag each thing into the pond. Does it sink or float? Tap the clay to change its shape.","cues":{"sink":"Down it goes! It sinks.","float":"It stays on top! The water pushes it up."}},"ep6":{"title":"What makes things happen?","hint":"Drag the pieces into the pot: soil, seed, water and sunshine. When the cause pie is full, wait and watch. Drag a piece back out to take it away, and try teddy too!","cues":{"wait":"The pie is full! Now we wait... causes take time.","grow":"All the pieces together... and the flower grows!","away":"Take one piece away... and it doesn't happen!","teddy":"Teddy is just there. Teddy is not a cause!","missing":"Something is missing, so the flower can't grow yet."}},"ep7":{"title":"Why do magnets stick?","hint":"Drag the magnet near each thing. Iron things jump to the magnet. Which ones stick?","cues":{"iron":"It sticks! That one has iron in it.","nope":"No pull. That one has no iron in it.","foil":"Foil is a metal, but it has no iron. No pull!","pull":"Red and blue pull together. Click!","push":"Red and red push apart! The same ends push each other away."},"tasks":[{"title":"Magnet test","hint":"Drag the magnet near each thing. Iron things jump to the magnet. Which ones stick?"},{"title":"Push or pull","hint":"Drag the magnet towards the other one. Tap it to turn it around. Which ends pull, and which push?"}]},"ep8":{"title":"How do we hear sounds?","hint":"Tap a string to pluck it. Long strings make low sounds and short strings make high sounds.","cues":{"low":"A long string wiggles more slowly. A low sound!","high":"A short string wiggles faster. A high sound!","quiet":"A small tap makes small wiggles: a quiet sound.","loud":"A big bang makes big wiggles: a loud sound! Look at the rice jump!"},"tasks":[{"title":"Pluck the strings","hint":"Tap a string to pluck it. Long strings make low sounds and short strings make high sounds."},{"title":"Tap the drum","hint":"Pull the drumstick back and let go. A small pull taps softly; a big pull bangs hard. Watch the rice!"}]},"ep9":{"title":"Why is it dark at night?","hint":"Drag around the Earth to spin it. Put Curie's house in the sunshine, then in the dark.","cues":{"day":"Curie's house faces the sun. It's daytime!","night":"Curie's house turned away from the sun. It's night!","sunrise":"The sun comes up. Good morning!","sunset":"The sun goes down. Good night!"},"tasks":[{"title":"Spin the Earth","hint":"Drag around the Earth to spin it. Put Curie's house in the sunshine, then in the dark."},{"title":"Sunrise, sunset","hint":"Spin the little Earth. Watch the sky over Curie's garden: the sun comes up, then goes down!"}]},"ep10":{"title":"Where does the sugar go?","hint":"Drag the sugar into the glass, then stir with the spoon (round and round). Where does it go? Tap Curie to taste!","cues":{"gone":"The sugar disappeared... or did it?","sweet":"Yum, sweet! The sugar is still there.","dissolves":"It dissolves! The tiny bits spread out in the water.","stays":"It doesn't dissolve. It sinks to the bottom and stays there."},"tasks":[{"title":"Stir the sugar","hint":"Drag the sugar into the glass, then stir with the spoon (round and round). Where does it go? Tap Curie to taste!"},{"title":"Does it dissolve?","hint":"Drag each jar into a glass. Which ones dissolve? Which ones sink and stay?"}]},"ep11":{"title":"Why do rolling things stop?","hint":"Pick a floor: ice, wood, carpet or grass. Then tap the car to let it go! Where does it stop?","cues":{"far":"Slippery ice hardly rubs at all. The car rolls a long, long way!","middle":"Smooth wood rubs a little. The car rolls quite far.","short":"Bumpy floors rub a lot. The car stops quickly!","slide":"On ice, a little push... and it slides and slides!","hard":"Sand rubs a lot. It's hard to push, and it stops right away!"},"tasks":[{"title":"Ramp race","hint":"Pick a floor: ice, wood, carpet or grass. Then tap the car to let it go! Where does it stop?"},{"title":"Push the box","hint":"Push the box along with your finger. On ice it slides easily; on sand it's hard work!"}]}},"videos":{"ep1":"https://youtu.be/X-jBQuLV9Jk","ep2":"https://youtu.be/PlfkVBF830E","ep3":"https://youtu.be/6TXyuOozO98","ep4":"https://youtu.be/7os5rLiTKPw","ep5":"https://youtu.be/HmYO-thndTA","ep6":"https://youtu.be/Bt2rQEQ8HDk","ep7":"https://youtu.be/rIY9Yfk7nh8","ep8":"https://youtu.be/HvZwQBTgaqo","ep9":"https://youtu.be/h2r1cMopdJc","ep10":"https://youtu.be/iVGf9KFRxYc","ep11":"https://youtu.be/S15KJvwr8uA"},"channel":"https://www.youtube.com/@LittleScientistsClubCurie","content":{"ep1":{"idea":"Heat makes things melt!","explain":"Ice cream is made of tiny bits. When it is cold they hold on to each other tightly, so the ice cream is hard: a solid. Warmth from the sun or a hand gives the bits energy, they wiggle apart and slide past each other, and the ice cream becomes a liquid. In the freezer the bits slow down and grab hold again.","play":"drag the sun","steps":["Ask a grown-up for two ice cubes and two small plates.","Put one plate in the sunshine and one in the shade.","Guess which cube will melt first, then check every few minutes.","Talk about it: what gave the ice cube heat?"],"quiz":[["What makes ice cream melt?",["Heat","Cold","Wind"],0],["Cold, hard ice cream is a...",["Solid","Liquid","Cloud"],0],["Where does melted ice cream go to get hard again?",["The freezer","The sun","The bath"],0]],"color":"#FF9BD2"},"ep2":{"idea":"Gravity pulls things down!","explain":"The Earth is enormous, and it pulls everything towards itself. We call that pull gravity. It is why a thrown ball always comes back down, why rain falls, and why our feet stay on the ground. Gravity makes big and small things fall together, so a big ball and a small ball dropped at the same time land together.","play":"throw the ball","steps":["Hold a ball in one hand and a toy car or a wooden block in the other, at the same height.","Count to three and let go of both at exactly the same time.","Watch closely: which one lands first? Try it again to be sure.","Now throw the ball up gently. Which way does it always go?"],"quiz":[["What pulls the ball back down?",["Gravity","The wind","A string"],0],["A big ball and a small ball dropped together land...",["Together","Big one first","Small one first"],0],["Gravity keeps your feet...",["On the ground","In the sky","In the sea"],0]],"color":"#9B6BFF"},"ep3":{"idea":"The sun lifts the water up, and the rain brings it down!","explain":"The sun warms the sea, and tiny bits of water float up into the air as invisible water vapour. High in the sky it is cold, so the bits huddle into droplets, and millions of droplets make a cloud. The droplets bump and join until they are too heavy to float, then they fall as rain, which runs back to the sea. Round and round: the water cycle.","play":"make it rain","steps":["Ask a grown-up for a glass or cup of very cold water with ice cubes.","Leave it on the table and wait a few minutes.","Look at the outside of the glass. Where did the little drops come from?","Breathe on a cold window or mirror and watch a tiny cloud appear."],"quiz":[["What lifts water up into the sky?",["The warm sun","The moon","A fan"],0],["Millions of tiny droplets make a...",["Cloud","Rock","Tree"],0],["Rain falls when the drops get too...",["Heavy","Light","Warm"],0]],"color":"#4EA8FF"},"ep4":{"idea":"A shadow is where the light can't go!","explain":"Light travels in straight lines. When it hits your body it stops, because it cannot go through you, so the ground or wall behind you gets no light. That dark patch is your shadow. When the sun is low in the morning or evening, shadows stretch long; at noon, when the sun is high, they are short.","play":"stretch a shadow","steps":["Ask a grown-up for a torch and make the room dark. Never shine it in anyone's eyes.","Shine the torch on a wall and put your hand in the light.","Make a dog, a bird or a rabbit with your hands.","Move your hand closer to the torch. Does the shadow get bigger or smaller?"],"quiz":[["A shadow is where...",["Light can't go","Light is brightest","Water is"],0],["When the sun is low, your shadow is...",["Long","Short","Gone"],0],["Light travels in...",["Straight lines","Circles","Zigzags"],0]],"color":"#FFB03B"},"ep5":{"idea":"Water pushes up!","explain":"When something sits in water it pushes some water out of the way, and the water pushes back up. A small, heavy stone pushes only a little water aside, so the push is too small and it sinks. A wide, hollow boat full of air pushes a lot of water aside, so the water pushes up hard enough to hold it. The same clay sinks as a ball and floats as a boat.","play":"sort things into the pond","steps":["Ask a grown-up for a bowl of water.","Collect a spoon, a coin, a cork, a plastic lid and a leaf.","Guess first: will it sink or float? Then drop it in.","Roll some clay or foil into a ball, then shape it into a boat. Test both!"],"quiz":[["Water pushes...",["Up","Down","Sideways"],0],["A small stone sinks because it pushes away only a little...",["Water","Air","Sand"],0],["The same clay floats when it is shaped like a...",["Boat","Ball","Cube"],0]],"color":"#5BC26B"},"ep6":{"idea":"Lots of pieces make it happen!","explain":"Things rarely have just one cause. A flower needs soil, a seed, water and sunshine all together, and it takes time. Epidemiologists draw this as a causal pie (Kenneth Rothman's sufficient-component cause model): each slice is a component cause, and the thing happens only when the whole pie is complete. The pieces need not act at the same time: the flower shows once the last piece has done its work (Rothman calls that gap the induction period). Because every slice is needed, taking any one away stops that pie, which is how prevention works: wash the germs off your hands and that tummy ache cannot happen. The same thing can also happen through a different pie (a flower can get its water from rain instead of a watering can), so removing one piece prevents the cases that needed it, not every case. To find out whether something really is a cause, scientists test it by taking it away and seeing whether the result changes. Teddy sat beside the pot all week, but the flower grew just the same without him: being there is not the same as being a cause.","play":"fill Curie's cause pie","steps":["Ask a grown-up for two clear cups, some cotton wool and two dried bean seeds.","Put cotton wool and a bean in each cup, and stand both cups on a sunny windowsill.","Water one cup a little every day so the wool stays damp. Keep the other cup dry.","Check every day for a week. Which bean grows? Which piece of the pie was missing?"],"quiz":[["What does a flower need to grow?",["All the pieces together","Just a seed","A teddy"],0],["Take one piece away and the flower...",["Does not grow","Grows faster","Turns blue"],0],["Teddy sat next to the pot every day. Is teddy a cause?",["No, teddy was just there","Yes, teddy made it grow","Only on Sundays"],0]],"color":"#E7C27A"},"ep7":{"idea":"Magnets pull iron!","explain":"A magnet pulls on things that contain iron, such as steel paper clips, iron nails, steel bottle caps and the steel door of many fridges (steel is mostly iron). Things without iron, such as wood, plastic, paper and leaves, are not pulled, and neither are most other metals: aluminium foil, most drink cans, copper and brass are not magnetic. The iron in foods such as spinach or dates is a tiny amount locked inside other substances, so a magnet does not pull them. Coins, keys and spoons vary, which makes them unreliable tests, and some stainless steel does not hold a magnet at all, so a steel paper clip is the surest first test. (Nickel and cobalt are magnetic too, but iron and steel are the ones children meet.) The pull works across a gap, even through paper, but we cannot see it. Every magnet has two ends, called poles (north and south, shown here as red and blue): opposite poles pull together and like poles push apart. Scientists find out which materials are magnetic by testing them one at a time, just as children do in the home experiment. Safety: use a large fridge magnet, and keep small, strong magnets away from young children because they are dangerous if swallowed.","play":"test things with a magnet","steps":["Ask a grown-up for a large fridge magnet. Magnets never go in your mouth.","Collect a paper clip, a pencil, a leaf and a piece of kitchen foil.","Guess first: will the magnet pull it? Then touch each thing with the flat back of the magnet (the side that sticks to the fridge) and sort them into two piles: pulled and not pulled.","Which things did the magnet pull? Talk about what they have in common. Then try the fridge door!"],"quiz":[["What does a magnet pull?",["Paper","Things with iron in them","Wood"],1],["Kitchen foil is shiny metal. Does a magnet pull it?",["Yes, every metal sticks","Only when it is cold","No, it has no iron"],2],["Two magnets, red end to red end. What happens?",["They push apart","They pull together","They melt"],0]],"color":"#FF5C5C"},"ep8":{"idea":"Sounds are wiggles!","explain":"Every sound starts with a vibration: something moving back and forth very quickly, such as a plucked string, a drum skin or the vocal cords in your throat. The vibrating object pushes on the air next to it, and each little bit of air passes the push on to the next bit, so a sound wave travels through the air to your ear. The air itself does not travel from the string to your ear; each bit only wiggles a little and passes the push along. In the ear, the wave makes the eardrum vibrate too, and the brain hears a sound. Two separate things change a sound. Bigger vibrations are louder (hit the drum harder and the rice jumps higher), and faster vibrations are higher (a short or tightly stretched string vibrates faster than a long or loose one, so it gives a higher note). Plucking the same string harder makes it louder, not higher. Humming with fingers on the throat lets children feel the vibration that makes their own voice.","play":"pluck strings and bang a drum","steps":["Ask a grown-up to join you. Put your fingers gently on your throat and hum. Can you feel the wiggle?","Ask your grown-up to stretch a rubber band over an open box or a plastic tub.","Pluck the rubber band gently, and keep it away from your face. Watch it wiggle and listen to the sound.","Ask your grown-up to pull the band at the side of the box a little tighter and hold it (not too tight!), then pluck again. Is the sound higher or lower?"],"quiz":[["What makes a sound?",["Something sleeping","Something wiggling","Something cold"],1],["A short string wiggles faster. Its sound is...",["Low","Silent","High"],2],["Bang the drum harder and the sound gets...",["Louder","Quieter","Colder"],0]],"color":"#2EC4B6"},"ep9":{"idea":"The Earth spins!","explain":"The Earth is a huge ball that spins all the time, making one full turn about every 24 hours. The sun does not switch off, go to sleep or travel round us at night: it keeps shining, but it can only light the half of the Earth that faces it, so that half has day and the half turned away is in shadow and has night. As the Earth turns, each place is carried into the sunlit half (morning), through the day, and out into the shadowed half (evening), so one full turn gives one day and one night. That is also why the sun seems to come up, cross the sky and go down, although it is really the ground under our feet that is turning. When it is midday on one side of the Earth it is midnight on the opposite side: midday in India, for example, is night-time in the Americas. In our pictures we look down from above the North Pole, where the Earth turns counter-clockwise. The pictures are not to scale: the sun is far bigger than the Earth and very far away. The torch-and-ball experiment is a small model: the torch is the sun, the ball is the Earth and the sticker is your home.","play":"spin the Earth","steps":["Ask a grown-up for a torch and a ball (an orange works too). Put a small sticker on it: that is your house.","Make the room dark. Your grown-up shines the torch at the ball from a few steps away (never into anyone's eyes), so the whole near half of the ball is lit up.","Turn the ball slowly, like the Earth spinning. Watch your sticker.","When is your house in the light, so it is day? When is it in the dark, so it is night?"],"quiz":[["Why do we have day and night?",["The sun switches off","The Earth spins","The moon hides the sun"],1],["When your side of the Earth faces the sun, it is...",["Day","Night","Bedtime"],0],["When it is day for you, on the other side of the Earth it is...",["Also day","Raining","Night"],2]],"color":"#3B4BA8"},"ep10":{"idea":"Sugar dissolves in water, but it's still there!","explain":"Sugar and salt are made of particles far too small to see, just like the ice cream in Episode 1. When sugar goes into water, the water particles pull the sugar particles away from the crystal, and they spread out evenly between the water particles: the sugar dissolves. We cannot see it any more, but it has not gone: the water tastes sweet, and if salty water is left to dry up, the salt crystals appear again. Dissolving is different from melting. Melting is a solid turning into a liquid when it is heated (Episode 1); dissolving is the particles of a solid spreading out through a liquid. Sugar dissolves even in cold water, just more slowly than in warm water, and stirring speeds it up by bringing fresh water to the crystals. Not everything dissolves: sand and pebbles sink to the bottom and stay there. Only taste with an adult's permission, and never taste the sand water.","play":"dissolve sugar in water","steps":["Ask a grown-up for two clear glasses of water, a spoon of sugar, a spoon of sand (or uncooked rice, if you have no sand) and two clean spoons for stirring.","Put the sugar in one glass and the sand in the other. Stir each glass with its own spoon for a minute or two, until you can't see the sugar. Then wash your hands.","Look closely: which one disappears? Which one sinks to the bottom and stays there?","With your grown-up's OK, taste a tiny sip of the sugar water. Is the sugar still there? How do you know? (Never taste the sand water, or the rice water!)"],"quiz":[["When sugar dissolves in water, the sugar is...",["Gone forever","Still there, in tiny bits","Turned into sand"],1],["Which one does NOT dissolve in water?",["Sand","Salt","Sugar"],0],["How can you tell the sugar is still in the water?",["The water turns green","The glass sings","The water tastes sweet"],2]],"color":"#F7B267"},"ep11":{"idea":"Rubbing slows it down!","explain":"A rolling or sliding object slows down because of friction, the force that acts where two surfaces rub against each other (air resistance adds a little). Rough or soft surfaces such as carpet, grass and sand produce more friction than smooth, hard ones, and ice produces very little, so the same car rolls much further on ice than on carpet. For wheels this is rolling friction: soft floors such as carpet squash under the wheels, and the axles rub a little. In the Try it activities the car and the box slow down steadily: the rougher the surface, the stronger the pull back, so the sooner they stop. Friction is also useful: it lets shoe soles grip the ground, lets us hold a pencil, and is how bicycle brakes stop the wheels. Letting the same car roll from the same place on different surfaces, as in the home experiment, is a fair test: only the surface changes, so any difference in distance comes from the surface.","play":"race a car down a ramp","steps":["Ask a grown-up to help you make a ramp: lean a big book against a cushion or a box.","Let a toy car roll down onto a smooth floor. Put a block where it stops.","Now spread a towel at the bottom of the ramp and roll the car again from the same place. Mark where it stops.","Where did it go further? Which floor rubbed more?"],"quiz":[["What slows a rolling car down?",["Sunshine","Rubbing","Singing"],1],["On which floor does the car roll the furthest?",["Grass","Carpet","Ice"],2],["Rubbing helps your shoes...",["Grip, so you don't slip","Change colour","Grow bigger"],0]],"color":"#E07A5F"}}};